import sys
from collections import defaultdict

MOD = 10**9 + 7

def dfs(node, parent, xor_value, visited, xor_map):
    xor_map[xor_value] += 1
    for neighbor, weight in adj[node]:
        if neighbor != parent:
            dfs(neighbor, node, xor_value ^ weight, visited, xor_map)

