    adj[u].append((v, t))
    adj[v].append((u, t))

result = 0
xor_map = defaultdict(int)

dfs(1, -1, 0, set(), xor_map)

for node in range(2, n + 1):
    new_xor_map = defaultdict(int)
    dfs(node, -1, 0, set(), new_xor_map)
    for x in xor_map:
        for y in new_xor_map:
